import Foundation

/// How to start a language server, and how to install it if missing.
struct ServerSpec {
    let command: String
    var args: [String] = []
    let install: String
    var initOptions: [String: Any]? = nil
}

enum LexerKind { case code, markup, css, markdown, yaml, toml, diff, plain }

struct Language: Identifiable, Hashable {
    let id: String              // LSP languageId
    let name: String
    var extensions: [String] = []
    var fileNames: [String] = []
    var lexer: LexerKind = .code
    var lineComment: String? = "//"
    var blockComment: (String, String)? = ("/*", "*/")
    var keywords: Set<String> = []
    var types: Set<String> = []
    var constants: Set<String> = []
    var builtins: Set<String> = []
    var strings: [String] = ["\"", "'"]
    var multilineStrings: Set<String> = []
    var charLiterals = false          // ' is a char literal (C, Rust, Java…)
    var capitalizedTypes = true
    var attributePrefix: Set<Character> = ["@"]
    var preprocessor = false          // #include …
    var variablePrefix: Character? = nil
    var caseInsensitive = false
    var stringPrefixes: Set<Character> = []
    var servers: [ServerSpec] = []
    var runFile: String? = nil        // {file} {dir} {name} {out}
    var serverID: String? = nil       // share one server between ids (ts/tsx/js)

    static func == (a: Language, b: Language) -> Bool { a.id == b.id }
    func hash(into h: inout Hasher) { h.combine(id) }

    var commentToggle: String? { lineComment ?? blockComment?.0 }

    /// Text for reading rather than code: wrapped, counted in words, no run/debug.
    var isProse: Bool { id == "plaintext" || id == "markdown" }

    static let plainText = Language(id: "plaintext", name: "Plain Text", lexer: .plain, lineComment: nil, blockComment: nil)

    static func detect(_ url: URL, firstLine: String? = nil) -> Language {
        let name = url.lastPathComponent
        let lower = name.lowercased()
        if let l = all.first(where: { $0.fileNames.contains(name) || $0.fileNames.contains(lower) }) { return l }
        let ext = url.pathExtension.lowercased()
        if !ext.isEmpty, let l = all.first(where: { $0.extensions.contains(ext) }) { return l }
        if lower.hasPrefix("dockerfile") { return byID("dockerfile") }
        if lower.hasPrefix(".env") { return byID("properties") }
        if let line = firstLine, line.hasPrefix("#!") {
            if line.contains("python") { return byID("python") }
            if line.contains("node") || line.contains("deno") || line.contains("bun") { return byID("javascript") }
            if line.contains("ruby") { return byID("ruby") }
            if line.contains("sh") { return byID("shellscript") }
        }
        return plainText
    }

    static func byID(_ id: String) -> Language { all.first { $0.id == id } ?? plainText }

    private static func w(_ s: String) -> Set<String> { Set(s.split(separator: " ").map(String.init)) }

    // MARK: - Definitions

    static let cKeywords = "auto break case char const continue default do double else enum extern float for goto if inline int long register restrict return short signed sizeof static struct switch typedef union unsigned void volatile while _Bool _Atomic bool"
    static let cppExtra = "alignas alignof and asm catch class concept consteval constexpr constinit co_await co_return co_yield decltype delete explicit export friend mutable namespace new noexcept not operator or private protected public requires static_assert static_cast dynamic_cast reinterpret_cast const_cast template this thread_local throw try typeid typename using virtual override final"
    static let jsKeywords = "async await break case catch class const continue debugger default delete do else export extends finally for from function get if import in instanceof let new of return set static super switch throw try typeof var void while with yield as"
    static let tsExtra = "abstract declare enum implements interface keyof namespace private protected public readonly type satisfies infer is module override unique"

