        let js = Language(id: "javascript", name: "JavaScript", extensions: ["js", "mjs", "cjs"], keywords: w(jsKeywords), types: w("Array Object String Number Boolean Promise Map Set Date RegExp Error Symbol BigInt JSON Math"), constants: w("true false null undefined this NaN Infinity"), builtins: w("console require module exports process window document"), strings: ["`", "\"", "'"], multilineStrings: ["`"], servers: [ServerSpec(command: "typescript-language-server", args: ["--stdio"], install: "npm install -g typescript typescript-language-server")], runFile: "node {file}", serverID: "typescript")
        let ts = Language(id: "typescript", name: "TypeScript", extensions: ["ts", "mts", "cts"], keywords: w(jsKeywords + " " + tsExtra), types: js.types.union(w("any unknown never void string number boolean object bigint symbol Record Partial Readonly Pick Omit")), constants: js.constants, builtins: js.builtins, strings: js.strings, multilineStrings: js.multilineStrings, servers: js.servers, runFile: "npx --yes tsx {file}", serverID: "typescript")
        let tsx = Language(id: "typescriptreact", name: "TSX", extensions: ["tsx"], keywords: ts.keywords, types: ts.types, constants: ts.constants, builtins: ts.builtins, strings: ts.strings, multilineStrings: ts.multilineStrings, servers: ts.servers, serverID: "typescript")
        let jsx = Language(id: "javascriptreact", name: "JSX", extensions: ["jsx"], keywords: js.keywords, types: js.types, constants: js.constants, builtins: js.builtins, strings: js.strings, multilineStrings: js.multilineStrings, servers: js.servers, serverID: "typescript")
        let cLike = Language(id: "c", name: "C", extensions: ["c", "h"], keywords: w(cKeywords), types: w("size_t ssize_t int8_t int16_t int32_t int64_t uint8_t uint16_t uint32_t uint64_t FILE"), constants: w("NULL true false"), builtins: w("printf malloc free memcpy strlen"), charLiterals: true, capitalizedTypes: false, attributePrefix: [], preprocessor: true, servers: [ServerSpec(command: "clangd", args: ["--background-index"], install: "xcode-select --install")], runFile: "clang -std=c17 -Wall {file} -o {out} && {out}", serverID: "clangd")

        return [
            Language(id: "swift", name: "Swift", extensions: ["swift"], keywords: w("actor associatedtype async await break case catch class continue convenience default defer deinit didSet do dynamic else enum extension fallthrough fileprivate final for func get guard if import in indirect infix init inout internal is lazy let mutating nonisolated nonmutating open operator optional override package postfix precedencegroup prefix private protocol public repeat required rethrows return set some any static struct subscript super switch throw throws try typealias unowned var weak where while willSet consume borrowing consuming macro"), types: w("Int Int8 Int16 Int32 Int64 UInt UInt8 UInt16 UInt32 UInt64 Double Float CGFloat Bool String Character Array Dictionary Set Optional Result Void Never Any AnyObject Self Data URL Date Error"), constants: w("true false nil self Self"), builtins: w("print debugPrint fatalError precondition assert min max abs zip stride"), strings: ["\"\"\"", "\""], multilineStrings: ["\"\"\""], attributePrefix: ["@", "#"], servers: [ServerSpec(command: "sourcekit-lsp", install: "xcode-select --install")], runFile: "swift {file}"),
            cLike,
            Language(id: "cpp", name: "C++", extensions: ["cpp", "cc", "cxx", "hpp", "hh", "hxx", "ipp", "tpp", "cppm"], keywords: w(cKeywords + " " + cppExtra), types: cLike.types.union(w("std string vector map unordered_map set shared_ptr unique_ptr optional variant array span string_view auto")), constants: w("nullptr NULL true false this"), builtins: w("cout cin cerr endl printf make_shared make_unique move forward"), charLiterals: true, capitalizedTypes: false, attributePrefix: [], preprocessor: true, servers: cLike.servers, runFile: "clang++ -std=c++20 -Wall {file} -o {out} && {out}", serverID: "clangd"),
            Language(id: "objective-c", name: "Objective-C", extensions: ["m"], keywords: w(cKeywords + " @interface @implementation @end @property @synthesize @protocol @class @selector @autoreleasepool @try @catch @finally @import id instancetype nonatomic strong weak copy assign readonly readwrite nullable nonnull self super"), types: w("NSString NSArray NSDictionary NSObject NSInteger NSUInteger BOOL CGFloat"), constants: w("YES NO nil NULL true false"), charLiterals: true, attributePrefix: ["@"], preprocessor: true, servers: cLike.servers, serverID: "clangd"),
            Language(id: "objective-cpp", name: "Objective-C++", extensions: ["mm"], keywords: w(cKeywords + " " + cppExtra), constants: w("YES NO nil nullptr true false"), charLiterals: true, preprocessor: true, servers: cLike.servers, serverID: "clangd"),
            Language(id: "csharp", name: "C#", extensions: ["cs", "csx"], keywords: w("abstract as base break case catch checked class const continue default delegate do else enum event explicit extern finally fixed for foreach goto if implicit in interface internal is lock namespace new operator out override params private protected public readonly record ref return sealed sizeof stackalloc static struct switch this throw try typeof unchecked unsafe using virtual volatile while async await var get set init value yield where when"), types: w("bool byte char decimal double float int long object sbyte short string uint ulong ushort void dynamic Task List Dictionary"), constants: w("true false null this"), charLiterals: true, attributePrefix: [], preprocessor: true, servers: [ServerSpec(command: "csharp-ls", install: "dotnet tool install --global csharp-ls")], runFile: "dotnet run"),
